SELECT 
FROM news_item
WHERE status = #{status}

ORDER BY review_time DESC, id DESC
LIMIT #{limit}

SELECT FROM news_item
AND status = #{query.status}
AND content_type = #{query.contentType}
AND channel_code = #{query.channelCode}
AND feed_id = #{query.feedId}
AND publish_time >= #{query.publishBegin}
AND publish_time <= #{query.publishEnd}
AND
CASE WHEN JSON_TYPE(JSON_EXTRACT(ai_values_json, '$.title')) = 'STRING' AND TRIM(JSON_UNQUOTE(JSON_EXTRACT(ai_values_json, '$.title'))) <> '' THEN JSON_UNQUOTE(JSON_EXTRACT(ai_values_json, '$.title')) ELSE origin_title END
origin_title
LIKE CONCAT('%', #{query.keyword}, '%')
AND
JSON_CONTAINS(ai_values_json, JSON_QUOTE(#{tagValue}), CONCAT('$.', #{tagFilter.fieldKey}))
ORDER BY publish_time, id
ORDER BY publish_time DESC, id DESC

SELECT COUNT(*)
FROM news_item
WHERE status = #{status}
